"""Request a visible walker arm pose for a source driver or directing officer.

CARLA's unified walker skeleton provides shoulder, arm, forearm and hand bones.
The returned request is not evidence that a driver saw or understood the pose.
"""


def request_bones(carla, side='R'):
    if side not in ('L', 'R'):
        raise ValueError('Select one modeled hand')
    # Parent-relative rotations follow CARLA's WalkerBoneControl contract.
    poses = ((f'crl_shoulder__{side}', (0, 0, -45 if side == 'R' else 45)),
             (f'crl_arm__{side}', (0, 0, -55 if side == 'R' else 55)),
             (f'crl_foreArm__{side}', (0, 0, -35 if side == 'R' else 35)),
             (f'crl_hand__{side}', (0, 90, 0)))
    return [(name, carla.Transform(rotation=carla.Rotation(pitch=pitch, yaw=yaw, roll=roll)))
            for name, (pitch, yaw, roll) in poses]


def apply_hand_signal(carla, walker, side='R'):
    """Submit and read back a custom arm pose; fail if Native lacks the API."""
    transforms = request_bones(carla, side)
    if hasattr(walker, 'set_bones') and hasattr(carla, 'WalkerBoneControlIn'):
        walker.set_bones(carla.WalkerBoneControlIn(transforms))
        if not hasattr(walker, 'show_pose'):
            raise ValueError('Native walker pose blending unavailable')
        walker.show_pose()
    elif hasattr(walker, 'apply_control') and hasattr(carla, 'WalkerBoneControl'):
        control = carla.WalkerBoneControl()
        control.bone_transforms = transforms
        walker.apply_control(control)
    else:
        raise ValueError('Native walker bone-control API unavailable')
    if not hasattr(walker, 'get_bones'):
        raise ValueError('Native walker bone readback unavailable')
    readback = walker.get_bones()
    names = {row.name if hasattr(row, 'name') else row[0] for row in readback.bone_transforms}
    requested = {name for name, _ in transforms}
    if not requested <= names:
        raise ValueError('Native hand-signal bones absent in readback')
    return {'requested_bones': sorted(requested), 'readback_bones': sorted(requested),
            'visual_visibility_verified': False}


def spawn_source_driver_proxy(carla, world, source_vehicle, blueprint_id,
                              offset_m=(0.0, -1.5, 0.0)):
    """Create a visible walker proxy beside the source vehicle for Native review.

    The proxy is an acquisition aid. Original camera review must establish that
    viewers understand it as the source driver and can see its hand signal.
    """
    if not blueprint_id.startswith('walker.pedestrian.'):
        raise ValueError('Source driver proxy must use a walker skeleton')
    vehicle_pose = source_vehicle.get_transform()
    location = vehicle_pose.location
    spawn = carla.Transform(
        carla.Location(x=location.x + offset_m[0],
                       y=location.y + offset_m[1],
                       z=location.z + offset_m[2]),
        carla.Rotation(yaw=vehicle_pose.rotation.yaw))
    walker = world.try_spawn_actor(world.get_blueprint_library().find(blueprint_id), spawn)
    if walker is None:
        raise RuntimeError('Reviewed source driver proxy spawn failed')
    return walker

"""Join original emergency, lane, lamp, exception and hand-signal sources.

The diagnostic mode exercises source rejection without claiming that a synthetic
fixture establishes authorization, visibility, safety, or legal compliance.
"""
import hashlib
import json
from pathlib import Path


ASSIGNMENT = "training__C405647__NRS-484B-267-2b__motor_vehicle_driver"
SOURCES = (
    "vehicle_authorization", "flashing_equipment", "flashing_qualification",
    "lamp_pixels", "lane_topology", "roadway_conditions", "traffic_conditions",
    "weather_conditions", "officer_direction", "hand_signal_pixels",
)


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def join(folder, case_id, diagnostic=False):
    folder = Path(folder)
    review_path = folder / "emergency-review.json"
    if not review_path.is_file():
        raise ValueError("Missing required source: emergency-review.json")
    review = json.loads(review_path.read_text())
    if review.get("assignment_id") != ASSIGNMENT or review.get("case_id") != case_id:
        raise ValueError("Emergency source review identity differs")
    kind = review.get("review_kind")
    if kind != ("synthetic_diagnostic" if diagnostic else "original_native"):
        raise ValueError("Original Native emergency source review required")
    role = review.get("qualification_role")
    if role not in {"authorized_emergency", "official_regulatory"}:
        raise ValueError("Emergency or official regulatory role source missing")
    expected_role = "official_regulatory" if case_id.endswith("probe_03") else "authorized_emergency"
    if role != expected_role:
        raise ValueError("Selected qualification role differs from source review")
    refs = review.get("sources")
    if not isinstance(refs, dict) or set(refs) != set(SOURCES):
        raise ValueError("Incomplete emergency source inventory")
    joined = {}
    for name in SOURCES:
        ref = refs[name]
        path = f"source_context/{name}.txt"
        source = folder / path
        if not source.is_file():
            raise ValueError("Missing required source: " + path)
        if ref.get("path") != path or ref.get("sha256") != sha(source):
            raise ValueError("Emergency source hash differs: " + name)
        if not source.read_text().strip():
            raise ValueError("Empty emergency source: " + name)
        joined[name] = ref["sha256"]
    if not diagnostic:
        required = (
            "vehicle_authorized", "flashing_equipment_qualifies",
            "flashing_lamps_reviewed_in_original_pixels", "lane_graph_reviewed",
            "roadway_reviewed", "traffic_reviewed", "weather_reviewed",
            "officer_direction_reviewed", "hand_signal_visibility_reviewed",
        )
        if any(type(review.get(key)) is not bool for key in required):
            raise ValueError("Original emergency statutory activation review incomplete")
        if not all(review[key] for key in required[:7]):
            raise ValueError("Original emergency activation source not established")
        if not review["officer_direction_reviewed"]:
            raise ValueError("Original officer direction source not reviewed")
        if case_id.endswith("probe_04") and not review["hand_signal_visibility_reviewed"]:
            raise ValueError("Original visible hand signal source not reviewed")
    return {"review_kind": kind, "qualification_role": role, "review_sha256": sha(review_path),
            "source_sha256": joined, "source_reviewed": not diagnostic,
            "legal_result": None}

"""Measure an original Native approach to a moving, flashing emergency vehicle."""

import math

FRAMES = 600
RATE_HZ = 20
CAMERAS = {"overview", "approach", "reference_corner", "driver_reference"}


def number(value, name):
    if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value):
        raise ValueError(f"Invalid {name}")
    return float(value)


def source_hash(value, name):
    if not isinstance(value, str) or len(value) != 64 or any(c not in "0123456789abcdef" for c in value):
        raise ValueError(f"Missing source hash: {name}")


def measure(context, rows):
    if context.get("source_kind") not in {"original_native_emergency_readback", "synthetic_cpu_emergency_readback"}:
        raise ValueError("Original Native or explicitly synthetic emergency readback missing")
    for name in ("native_map_sha256", "ego_blueprint_sha256", "emergency_actor_sha256",
                 "emergency_role_source_sha256", "flashing_lamp_source_sha256", "vehicle_extent_sha256",
                 "visibility_source_sha256", "officer_direction_source_sha256"):
        source_hash(context.get(name), name)
    if context.get("emergency_role") not in {"authorized_emergency", "official_regulatory"}:
        raise ValueError("Qualifying vehicle role missing")
    if context.get("lamps_meet_nrs_484a_480_3") is not True:
        raise ValueError("Qualifying flashing-lamp evidence missing")
    mode = context.get("activation_mode")
    if mode not in {"moving_vehicle", "visible_hand_signal"}:
        raise ValueError("Moving or visibly preparing activation not sourced")
    if len(rows) != FRAMES:
        raise ValueError("Incomplete 30-second Native trace")
    prior_native = None
    passing = []
    approaching = []
    officer = set()
    speeds = []
    gaps = []
    hard = []
    for i, row in enumerate(rows):
        if row.get("video_frame") != i:
            raise ValueError("Video frame identity gap")
        native = row.get("native_frame")
        if type(native) is not int or (prior_native is not None and native <= prior_native):
            raise ValueError("Native frame identity gap")
        prior_native = native
        if abs(number(row.get("time_s"), "Native time") - i / RATE_HZ) > 1e-6:
            raise ValueError("Native time join failed")
        cameras = row.get("source_cameras")
        if not isinstance(cameras, dict) or set(cameras) != CAMERAS or any(cameras[c] != i for c in CAMERAS):
            raise ValueError("Four source camera frame join failed")
        if row.get("emergency_visible") not in (True, False):
            raise ValueError("Visibility observation missing")
        if row.get("flashing_lamps_visible") not in (True, False):
            raise ValueError("Flashing lamps observation missing")
        if row.get("officer_direction") not in {"none", "proceed", "stop", "other"}:
            raise ValueError("Officer direction source missing")
        if row.get("hand_signal_visible") not in (True, False):
            raise ValueError("Visible preparation source missing")
        officer.add(row["officer_direction"])
        ego_x = number(row.get("ego_center_x_m"), "ego position")
        emergency_x = number(row.get("emergency_center_x_m"), "emergency position")
        ego_speed = number(row.get("ego_speed_mps"), "ego speed")
        emergency_speed = number(row.get("emergency_speed_mps"), "emergency speed")
        gap = number(row.get("surface_gap_m"), "surface gap")
        deceleration = number(row.get("ego_deceleration_mps2"), "ego deceleration")
        if ego_speed < 0 or emergency_speed < 0 or gap < 0:
            raise ValueError("Negative speed or surface gap")
        activated = emergency_speed > 0.1 if mode == "moving_vehicle" else row["hand_signal_visible"]
        if row["emergency_visible"] and row["flashing_lamps_visible"] and activated and ego_x < emergency_x:
            approaching.append(i)
        if abs(ego_x - emergency_x) <= 4.5 and row["emergency_visible"]:
            passing.append(i)
        speeds.append(ego_speed)
        gaps.append(gap)
        hard.append(deceleration >= 3.0)
    if not approaching:
        raise ValueError("No sourced approach to moving flashing vehicle")
    if not passing:
        raise ValueError("No sourced passing interval")
    first = approaching[0]
    if not rows[first]["emergency_visible"] or not rows[first]["flashing_lamps_visible"]:
        raise ValueError("Emergency indication not visible on approach")
    first_pass = passing[0]
    relative_speed = max(0.0, speeds[first] - number(rows[first]["emergency_speed_mps"], "emergency speed"))
    longitudinal_gap = number(rows[first]["emergency_center_x_m"], "emergency x") - number(rows[first]["ego_center_x_m"], "ego x")
    ttc = longitudinal_gap / relative_speed if relative_speed > 0.01 else None
    return {"format": "worker-source-emergency-approach-measurement",
            "frame_count": FRAMES, "rate_hz": RATE_HZ,
            "diagnostic_only": context["source_kind"] == "synthetic_cpu_emergency_readback",
            "activation_mode": mode,
            "qualifying_role": context["emergency_role"],
            "first_approach_frame": first, "first_passing_frame": first_pass,
            "approach_time_to_conflict_s": ttc,
            "minimum_passing_surface_gap_m": min(gaps[i] for i in passing),
            "ego_speed_at_first_pass_mps": speeds[first_pass],
            "hard_deceleration_frames": [i for i, value in enumerate(hard) if value],
            "officer_direction_states": sorted(officer),
            "legal_compliance": "unassessed",
            "limitations": ["Proceed with caution is qualitative; speed, clearance, TTC and braking are diagnostics, not a statutory cutoff.",
                            "Lamp qualification, vehicle authorization, and visibility need original source and independent review.",
                            "An officer direction changes the applicable response and requires separate branch review."]}
